(4728709, 681489, 46177, '<td valign="top">Hmmmmm, nice scenery! 9</td>', 'Hmmmmm, nice scenery! 9', '2008-05-28 01:09:02.000000', NULL, 1),
(4728737, 682260, 93927, '<td valign="top">Beautiful!<br/>...and the picture''s not bad either :)<br/> <br/>Nice ring light! Great composition. Well done!<br/>10.</td>', 'Beautiful!...and the picture''s not bad either :) Nice ring light! Great composition. Well done!10.', '2008-05-28 01:15:29.000000', NULL, 1),
(4728744, 682896, 93927, '<td valign="top">I think the HDR look is a little much in this image. It''s almost scary.</td>', 'I think the HDR look is a little much in this image. It''s almost scary.', '2008-05-28 01:17:26.000000', NULL, 1),
(4728747, 682260, 73452, '<td valign="top">oh mylord, this man is so gorgeous, those eyes are amazing,nice use of a ring light.   Colors are very nicely complimenting his skin. Nicely done</td>', 'oh mylord, this man is so gorgeous, those eyes are amazing,nice use of a ring light.   Colors are very nicely complimenting his skin. Nicely done', '2008-05-28 01:17:42.000000', NULL, 1),
(4728754, 682469, 93927, '<td valign="top">This image jumped out at me from the rest, but I''m sure everyone will say the same thing... it''s too small :(</td>', 'This image jumped out at me from the rest, but I''m sure everyone will say the same thing... it''s too small :(', '2008-05-28 01:18:53.000000', NULL, 1),
(4728761, 680727, 73452, '<td valign="top">awesome moody portrait, love the use of lighting, and the processing done.  Great Job.</td>', 'awesome moody portrait, love the use of lighting, and the processing done.  Great Job.', '2008-05-28 01:21:32.000000', NULL, 1),
(4728772, 682395, 8624, '<td valign="top">I would have preferred to see the interesting beads and outfit in color</td>', 'I would have preferred to see the interesting beads and outfit in color', '2008-05-28 01:24:47.000000', NULL, 1),
(4728807, 682602, 8624, '<td valign="top">his shoulder is pretty overexposed</td>', 'his shoulder is pretty overexposed', '2008-05-28 01:36:31.000000', NULL, 1),
(4728808, 682729, 8624, '<td valign="top">interesting hair and stubble. background is too cluttered.</td>', 'interesting hair and stubble. background is too cluttered.', '2008-05-28 01:36:59.000000', NULL, 1),
(4728812, 682894, 8624, '<td valign="top">fun use of selective desat. flash is too harsh on the pacifier.</td>', 'fun use of selective desat. flash is too harsh on the pacifier.', '2008-05-28 01:37:58.000000', NULL, 1),
(4728822, 682683, 8624, '<td valign="top">way underexposed. I get that you wanted to show the subject lit by the flames, but I can hardly see him.</td>', 'way underexposed. I get that you wanted to show the subject lit by the flames, but I can hardly see him.', '2008-05-28 01:39:13.000000', NULL, 1),
(4728830, 682426, 77521, '<td valign="top">gorgeous eyes! wow. great shot, 10</td>', 'gorgeous eyes! wow. great shot, 10', '2008-05-28 01:40:48.000000', NULL, 1),
(4728833, 682960, 8624, '<td valign="top">would have preferred better lighting on his hat</td>', 'would have preferred better lighting on his hat', '2008-05-28 01:41:34.000000', NULL, 1),
(4728839, 682962, 8624, '<td valign="top">great character. wish the hand was more in focus and occluding less of his beard.</td>', 'great character. wish the hand was more in focus and occluding less of his beard.', '2008-05-28 01:42:21.000000', NULL, 1),
(4728851, 682527, 8624, '<td valign="top">cool perspective, but I don''t like how the boat wake is coming out of his nose</td>', 'cool perspective, but I don''t like how the boat wake is coming out of his nose', '2008-05-28 01:46:12.000000', NULL, 1),
(4728856, 681635, 8624, '<td valign="top">nicely lit and composed. lose the watch next time - too distracting.</td>', 'nicely lit and composed. lose the watch next time - too distracting.', '2008-05-28 01:46:54.000000', NULL, 1),
(4728859, 682963, 8624, '<td valign="top">cool character. need to backlight or side light the hat to provide better separation from your background.</td>', 'cool character. need to backlight or side light the hat to provide better separation from your background.', '2008-05-28 01:48:03.000000', NULL, 1),
(4728863, 682896, 8624, '<td valign="top">cool face - way oversharpened</td>', 'cool face - way oversharpened', '2008-05-28 01:50:04.000000', NULL, 1),
(4728885, 682896, 90624, '<td valign="top">Lil less sharpening</td>', 'Lil less sharpening', '2008-05-28 01:58:19.000000', NULL, 1),
(4728892, 682287, 93883, '<td valign="top">He should be celebrating!  His team just won the Premiership AND the Championship!</td>', 'He should be celebrating!  His team just won the Premiership AND the Championship!', '2008-05-28 02:00:58.000000', NULL, 1),
(4728944, 682915, 67237, '<td valign="top">i think we have winner here.....this stands out among the bunch of snapshots and poor images in the show</td>', 'i think we have winner here.....this stands out among the bunch of snapshots and poor images in the show', '2008-05-28 02:35:28.000000', NULL, 1),
(4728948, 681696, 26559, '<td valign="top">Nice background and good, unobtrusive use of fill (I''m assuming, since it''s backlit).  Lack of sharp focus detracts from the image, though.</td>', 'Nice background and good, unobtrusive use of fill (I''m assuming, since it''s backlit).  Lack of sharp focus detracts from the image, though.', '2008-05-28 02:38:16.000000', NULL, 1),
(4728950, 681250, 26559, '<td valign="top">Great contrast, rich blacks really make the subject pop.  Whatever he is doing with his hands draws my eye out of the frame, though.  Wish they were in the frame.</td>', 'Great contrast, rich blacks really make the subject pop.  Whatever he is doing with his hands draws my eye out of the frame, though.  Wish they were in the frame.', '2008-05-28 02:39:40.000000', NULL, 1),
(4728952, 682260, 26559, '<td valign="top">Good eye connection with the viewer.  Not sure if I like the slanted perspective, makes it look like he''s trapped in a room with a low ceiling and can''t stand up straight.  =)</td>', 'Good eye connection with the viewer.  Not sure if I like the slanted perspective, makes it look like he''s trapped in a room with a low ceiling and can''t stand up straight.  =)', '2008-05-28 02:41:29.000000', NULL, 1),
(4728955, 682950, 26559, '<td valign="top">Seems a little unsharp around the mouth particularly...maybe a little more depth of field would improve.  The background is distracting, and the brown sofa, brown shirt, and brown walls don''t let the subject pop as much as I''d like.</td>', 'Seems a little unsharp around the mouth particularly...maybe a little more depth of field would improve.  The background is distracting, and the brown sofa, brown shirt, and brown walls don''t let the subject pop as much as I''d like.', '2008-05-28 02:43:19.000000', NULL, 1),
(4728957, 682568, 26559, '<td valign="top">Love the cross-lighting, particularly the rim light on the left subject.  The background is a little busy, and I''d like it better if the subjects were closer together (their heads, particularly).</td>', 'Love the cross-lighting, particularly the rim light on the left subject.  The background is a little busy, and I''d like it better if the subjects were closer together (their heads, particularly).', '2008-05-28 02:45:15.000000', NULL, 1),
(4728959, 682336, 26559, '<td valign="top">Love the sharpness.  The light is a little harsh, but I think the B&amp;W treatment makes that work a lot better.   Perhaps cropped a little tight for my tastes.</td>', 'Love the sharpness.  The light is a little harsh, but I think the B&W treatment makes that work a lot better.   Perhaps cropped a little tight for my tastes.', '2008-05-28 02:46:44.000000', NULL, 1),
(4728962, 682798, 26559, '<td valign="top">The angle on this one is a little odd.  I''d love to see a brighter catchlight in the eyes, and some different lighting to separate the subject from the background better (the hair and the background are very similar tone).</td>', 'The angle on this one is a little odd.  I''d love to see a brighter catchlight in the eyes, and some different lighting to separate the subject from the background better (the hair and the background are very similar tone).', '2008-05-28 02:49:20.000000', NULL, 1),
(4728969, 682623, 26559, '<td valign="top">I''m a sucker for the dramatic B&amp;W floating head look, strong initial impact.  I''d love to see the head a little more off center towards one of the corners, and maybe a little tighter crop.</td>', 'I''m a sucker for the dramatic B&W floating head look, strong initial impact.  I''d love to see the head a little more off center towards one of the corners, and maybe a little tighter crop.', '2008-05-28 02:51:37.000000', NULL, 1),
(4728976, 682539, 26559, '<td valign="top">Love the subject and the grainy, high-contrast treatment.  Hate the black bars.  Would love to see a tiny bit looser crop over his head, but that may be constrained by the original capture.</td>', 'Love the subject and the grainy, high-contrast treatment.  Hate the black bars.  Would love to see a tiny bit looser crop over his head, but that may be constrained by the original capture.', '2008-05-28 02:53:23.000000', NULL, 1),
(4728980, 681883, 87502, '<td valign="top">handsome subject, you should lighted his face better.  His shirt has more impact than he does.</td>', 'handsome subject, you should lighted his face better.  His shirt has more impact than he does.', '2008-05-28 02:54:32.000000', NULL, 1),
(4728981, 682004, 26559, '<td valign="top">Kudos on getting your eye in such good focus on a self portrait.  I''d like to see more depth of field, especially on a shot like this with a white background where blurring the background isn''t so critical.</td>', 'Kudos on getting your eye in such good focus on a self portrait.  I''d like to see more depth of field, especially on a shot like this with a white background where blurring the background isn''t so critical.', '2008-05-28 02:54:58.000000', NULL, 1),
(4728984, 682347, 26559, '<td valign="top">I like the catchlights in the eyes.</td>', 'I like the catchlights in the eyes.', '2008-05-28 02:55:55.000000', NULL, 1),
(4728998, 682957, 26559, '<td valign="top">Interesting pose.  Looks like a midday shot...I''d love to see the lighting reversed...more/better light on subject, less light on background (sky is blown out and detracts from subject).</td>', 'Interesting pose.  Looks like a midday shot...I''d love to see the lighting reversed...more/better light on subject, less light on background (sky is blown out and detracts from subject).', '2008-05-28 02:58:54.000000', NULL, 1),
(4729001, 682255, 26559, '<td valign="top">I like the lighting and the dark/light contrast, though I think the light part is a little underexposed for my taste.</td>', 'I like the lighting and the dark/light contrast, though I think the light part is a little underexposed for my taste.', '2008-05-28 03:00:35.000000', NULL, 1),
(4729002, 681342, 26559, '<td valign="top">Is this a soft-focus shot?  He almost seems to glow!  The red shirt is a little distracting, might be interesting to try a B&amp;W treatment on this.</td>', 'Is this a soft-focus shot?  He almost seems to glow!  The red shirt is a little distracting, might be interesting to try a B&W treatment on this.', '2008-05-28 03:02:10.000000', NULL, 1),
(4729004, 682726, 26559, '<td valign="top">More interesting than your average headshot, kudos.  The face seems unsharp to me, I''d love to see it crisper.</td>', 'More interesting than your average headshot, kudos.  The face seems unsharp to me, I''d love to see it crisper.', '2008-05-28 03:03:52.000000', NULL, 1),
(4729008, 682953, 26559, '<td valign="top">Interesting idea (and patient model!) The texture and the light patterns compete with each other a little, I''d rather see this simplified to just one strong lighting or textural element.</td>', 'Interesting idea (and patient model!) The texture and the light patterns compete with each other a little, I''d rather see this simplified to just one strong lighting or textural element.', '2008-05-28 03:06:10.000000', NULL, 1),
(4729017, 682443, 26559, '<td valign="top">Cool idea, must have been tough to get aligned just right.  Seems just a tad unsharp to me overall, hard to tell.</td>', 'Cool idea, must have been tough to get aligned just right.  Seems just a tad unsharp to me overall, hard to tell.', '2008-05-28 03:11:16.000000', NULL, 1),
(4729021, 682625, 26559, '<td valign="top">B&amp;W treatment is great on this, I like the lighting on the neck perspiration.</td>', 'B&W treatment is great on this, I like the lighting on the neck perspiration.', '2008-05-28 03:12:55.000000', NULL, 1),
(4729025, 682443, 28742, '<td valign="top">Alas, I fear your gimmick will backfire - the underlying portrait would have done well on it''s own, IMO. Good luck though.</td>', 'Alas, I fear your gimmick will backfire - the underlying portrait would have done well on it''s own, IMO. Good luck though.', '2008-05-28 03:15:48.000000', NULL, 1),
(4729026, 681164, 26559, '<td valign="top">Love the lighting.  Face seems unsharp, I''d love to see this same shot with really crisp detail.</td>', 'Love the lighting.  Face seems unsharp, I''d love to see this same shot with really crisp detail.', '2008-05-28 03:16:41.000000', NULL, 1),
(4729027, 682288, 93883, '<td valign="top">props on what must have been a fun makeup job!</td>', 'props on what must have been a fun makeup job!', '2008-05-28 03:17:00.000000', NULL, 1),
(4729028, 682956, 26559, '<td valign="top">Very contrasty, and the busy leaf patterns and ripples detract from the subject.</td>', 'Very contrasty, and the busy leaf patterns and ripples detract from the subject.', '2008-05-28 03:18:35.000000', NULL, 1),
(4729030, 682742, 28742, '<td valign="top">Kinda looks like the "Ethan" character from "Lost" - but not as creepy of course. Nice job - unique and still nicely done.</td>', 'Kinda looks like the "Ethan" character from "Lost" - but not as creepy of course. Nice job - unique and still nicely done.', '2008-05-28 03:19:25.000000', NULL, 1),
(4729031, 682758, 26559, '<td valign="top">Love the vibrant colors.  The background is a little distracting, and I would love it if his feet and feathers were not cut off.</td>', 'Love the vibrant colors.  The background is a little distracting, and I would love it if his feet and feathers were not cut off.', '2008-05-28 03:19:38.000000', NULL, 1),
(4729032, 681076, 28742, '<td valign="top">I have to take one point off for the popcorn ceiling. ;-)</td>', 'I have to take one point off for the popcorn ceiling. ;-)', '2008-05-28 03:20:24.000000', NULL, 1),
(4729034, 681158, 26559, '<td valign="top">The subject doesn''t really pop due to the statue which has almost equal treatment in the picture, and the background which is still distractingly sharp.</td>', 'The subject doesn''t really pop due to the statue which has almost equal treatment in the picture, and the background which is still distractingly sharp.', '2008-05-28 03:20:56.000000', NULL, 1),
(4729035, 682600, 26559, '<td valign="top">I like the pose, the lighting, the composition, and the grain but I''m not fond of the blur, even though it may well be intended.</td>', 'I like the pose, the lighting, the composition, and the grain but I''m not fond of the blur, even though it may well be intended.', '2008-05-28 03:22:21.000000', NULL, 1),
(4729038, 681616, 26559, '<td valign="top">Nice sharp capture, but the midday lighting is fairly harsh and detracts from the shot.</td>', 'Nice sharp capture, but the midday lighting is fairly harsh and detracts from the shot.', '2008-05-28 03:24:03.000000', NULL, 1),
(4729040, 682538, 26559, '<td valign="top">Great action capture, but in my opinion needs a wider crop and less depth of field to really show off the subject.</td>', 'Great action capture, but in my opinion needs a wider crop and less depth of field to really show off the subject.', '2008-05-28 03:25:39.000000', NULL, 1),
(4729042, 682783, 28742, '<td valign="top">Very nice use of natural light - excellent exposure! He looks like Jamie Foxx (who never appeared in the TV Series "Lost"). I''ll eplain later. Good luck and well done.</td>', 'Very nice use of natural light - excellent exposure! He looks like Jamie Foxx (who never appeared in the TV Series "Lost"). I''ll eplain later. Good luck and well done.', '2008-05-28 03:25:55.000000', NULL, 1),
(4729045, 682617, 26559, '<td valign="top">I like the setting, the composition, and the contrasting orange shirt.  Face seems a little unsharp, and the lighting is a little harsh and not very dramatic.</td>', 'I like the setting, the composition, and the contrasting orange shirt.  Face seems a little unsharp, and the lighting is a little harsh and not very dramatic.', '2008-05-28 03:27:02.000000', NULL, 1),
(4729048, 681686, 28742, '<td valign="top">That has to top my list of the cutest smiles I have ever seen photographed. Great composition and overall excellent portrait.</td>', 'That has to top my list of the cutest smiles I have ever seen photographed. Great composition and overall excellent portrait.', '2008-05-28 03:28:20.000000', NULL, 1),
(4729051, 682692, 26559, '<td valign="top">Needs a better background.  I don''t like the blue cast on the face, but it seems like it may be from taking your own picture in front of a computer monitor.  And it seems a little unsharp, like my self-portraits always turn out  =)</td>', 'Needs a better background.  I don''t like the blue cast on the face, but it seems like it may be from taking your own picture in front of a computer monitor.  And it seems a little unsharp, like my self-portraits always turn out  =)', '2008-05-28 03:29:43.000000', NULL, 1),
(4729052, 682540, 28742, '<td valign="top">This boy certainly looks lively and energetic! ...ok, a little psycho as well. ;-)</td>', 'This boy certainly looks lively and energetic! ...ok, a little psycho as well. ;-)', '2008-05-28 03:29:46.000000', NULL, 1),
(4729054, 682786, 26559, '<td valign="top">I like the B&amp;W treatment.</td>', 'I like the B&W treatment.', '2008-05-28 03:30:08.000000', NULL, 1),
(4729055, 681244, 26559, '<td valign="top">Background is quite distracting.</td>', 'Background is quite distracting.', '2008-05-28 03:31:23.000000', NULL, 1),
(4729056, 681300, 28742, '<td valign="top">Hey man, with the price of gas, a guy''s gotta do what he can to get to work. :) Portrait? I think not. But a point for humor nonetheless.</td>', 'Hey man, with the price of gas, a guy''s gotta do what he can to get to work. :) Portrait? I think not. But a point for humor nonetheless.', '2008-05-28 03:31:34.000000', NULL, 1),
(4729059, 682402, 26559, '<td valign="top">Interesting shot, but it''s hard to tell what the subject is because of all the distracting elements.</td>', 'Interesting shot, but it''s hard to tell what the subject is because of all the distracting elements.', '2008-05-28 03:32:36.000000', NULL, 1),
(4729062, 682105, 26559, '<td valign="top">LOVE it.  Sharp, simple, interesting.  Well lit, too.  Best shot so far.</td>', 'LOVE it.  Sharp, simple, interesting.  Well lit, too.  Best shot so far.', '2008-05-28 03:33:49.000000', NULL, 1),
(4729065, 682395, 26559, '<td valign="top">Great, interesting subject.  I''d love to see a little more contrast, deeper blacks and whiter whites.</td>', 'Great, interesting subject.  I''d love to see a little more contrast, deeper blacks and whiter whites.', '2008-05-28 03:34:58.000000', NULL, 1),
(4729067, 682787, 26559, '<td valign="top">A hair light from the back might help to separate the subject from the background a little more.</td>', 'A hair light from the back might help to separate the subject from the background a little more.', '2008-05-28 03:35:39.000000', NULL, 1),
(4729069, 682738, 26559, '<td valign="top">Helps to have a model who is cut =)  Excellent lighting.  I don''t like the angle, though.</td>', 'Helps to have a model who is cut =)  Excellent lighting.  I don''t like the angle, though.', '2008-05-28 03:36:35.000000', NULL, 1),
(4729072, 682620, 26559, '<td valign="top">A little unsharp, and pretty low-contrast.  It''s just a little flat and the subject doesn''t really pop.</td>', 'A little unsharp, and pretty low-contrast.  It''s just a little flat and the subject doesn''t really pop.', '2008-05-28 03:38:02.000000', NULL, 1),
(4729075, 682602, 26559, '<td valign="top">I like the pose, maybe could show a little more face to have more connection with the eyes.</td>', 'I like the pose, maybe could show a little more face to have more connection with the eyes.', '2008-05-28 03:39:05.000000', NULL, 1),
(4729079, 682719, 26559, '<td valign="top">Hard to "connect" with the bass player since I can''t see his eyes, makes it tough to get drawn into the image.</td>', 'Hard to "connect" with the bass player since I can''t see his eyes, makes it tough to get drawn into the image.', '2008-05-28 03:40:52.000000', NULL, 1),
(4729080, 681185, 28742, '<td valign="top">Wow! So many lackluster entries in this challenge - a few stand out as outstanding, this is one of them. An easy 10 from me. <br/> <br/>ps: get a haircut, hippie!</td>', 'Wow! So many lackluster entries in this challenge - a few stand out as outstanding, this is one of them. An easy 10 from me.  ps: get a haircut, hippie!', '2008-05-28 03:41:41.000000', NULL, 1),
(4729081, 681192, 26559, '<td valign="top">Too underexposed for my taste, and the subject doesn''t really pop.</td>', 'Too underexposed for my taste, and the subject doesn''t really pop.', '2008-05-28 03:42:21.000000', NULL, 1),
(4729082, 682320, 26559, '<td valign="top">I find myself more drawn to the engine than the person, so this might work better as a portrait if you found a way to show more of the man and less of the background.</td>', 'I find myself more drawn to the engine than the person, so this might work better as a portrait if you found a way to show more of the man and less of the background.', '2008-05-28 03:43:34.000000', NULL, 1),
(4729083, 682945, 28742, '<td valign="top">Sing us a song, you''re the piano boy<br/>sing us a song tonight<br/>for we''re all in the mood for a melody<br/>and that face is just cracking me up!  LOL<br/> <br/>What a gem!</td>', 'Sing us a song, you''re the piano boysing us a song tonightfor we''re all in the mood for a melodyand that face is just cracking me up!  LOL What a gem!', '2008-05-28 03:43:46.000000', NULL, 1),
(4729085, 682471, 28742, '<td valign="top">This will be my third comparison to a "Lost" (tv series) character so far in this challenge. Young Ben. :) Nice job, but a little dark - not just the lighting but the expression as well. A little smile won''t hurt. :)</td>', 'This will be my third comparison to a "Lost" (tv series) character so far in this challenge. Young Ben. :) Nice job, but a little dark - not just the lighting but the expression as well. A little smile won''t hurt. :)', '2008-05-28 03:45:30.000000', NULL, 1),
(4729086, 682975, 26559, '<td valign="top">The heart is in focus, but the subject is not.  And the heart is more colorful and more evenly lit than you are.  Great idea and I like the lighting on you, but you just need to emphasize the subject more.</td>', 'The heart is in focus, but the subject is not.  And the heart is more colorful and more evenly lit than you are.  Great idea and I like the lighting on you, but you just need to emphasize the subject more.', '2008-05-28 03:46:20.000000', NULL, 1),
(4729087, 681391, 28742, '<td valign="top">Too bad the spycam resolution is only 1MP. ;-) Just ribbin ya, but the image is unfortunately too small - does a decent portrait a large disservice and makes it hard to judge it''s true quality. I''ll give it a 6, but feel like I''m voting on a thumbnail. Good luck though.</td>', 'Too bad the spycam resolution is only 1MP. ;-) Just ribbin ya, but the image is unfortunately too small - does a decent portrait a large disservice and makes it hard to judge it''s true quality. I''ll give it a 6, but feel like I''m voting on a thumbnail. Good luck though.', '2008-05-28 03:47:37.000000', NULL, 1),
(4729090, 682255, 28742, '<td valign="top">Cashing in on the crying game, huh? Well done! :)</td>', 'Cashing in on the crying game, huh? Well done! :)', '2008-05-28 03:49:16.000000', NULL, 1),
(4729091, 682414, 28742, '<td valign="top">He''s one of the bad dudes from the Matrix, right? ;-) Great lighting! Very dramatic.</td>', 'He''s one of the bad dudes from the Matrix, right? ;-) Great lighting! Very dramatic.', '2008-05-28 03:50:23.000000', NULL, 1),
(4729092, 682245, 26559, '<td valign="top">Three of the four images are blurred.  And I would like to see the images aligned better.</td>', 'Three of the four images are blurred.  And I would like to see the images aligned better.', '2008-05-28 03:50:36.000000', NULL, 1),
(4729093, 682953, 28742, '<td valign="top">Dorian Gray? ;-)</td>', 'Dorian Gray? ;-)', '2008-05-28 03:50:52.000000', NULL, 1),
(4729094, 682477, 26559, '<td valign="top">I like the juxtaposition of all the eyes, and the strong eye contact with the subject.</td>', 'I like the juxtaposition of all the eyes, and the strong eye contact with the subject.', '2008-05-28 03:51:03.000000', NULL, 1),
