(4730328, 682974, 74703, '<td valign="top">i dig the lighting</td>', 'i dig the lighting', '2008-05-28 14:27:50.000000', NULL, 1),
(4730350, 682469, 61961, '<td valign="top">Nice "smouldering" look.  You should check the tutorials and forums for advice on how to resize a photo so you can keep 640 pixels without going over 150kb (and without losing all detail).</td>', 'Nice "smouldering" look.  You should check the tutorials and forums for advice on how to resize a photo so you can keep 640 pixels without going over 150kb (and without losing all detail).', '2008-05-28 14:39:37.000000', NULL, 1),
