(4730494, 681334, 88590, '<td valign="top">I quite like your photo, but found myself spending too much time wondering what was in front of the man.  Maybe if it was a little more discernable...?  Otherwise, great execution.</td>', 'I quite like your photo, but found myself spending too much time wondering what was in front of the man.  Maybe if it was a little more discernable...?  Otherwise, great execution.', '2008-05-28 15:34:55.000000', NULL, 1),
(4730501, 682127, 88590, '<td valign="top">Nice idea - very original.  Just a bit too dark for my liking.  It would have been better if you had a bit of fill light from the front.  Otherwise, good portrait.</td>', 'Nice idea - very original.  Just a bit too dark for my liking.  It would have been better if you had a bit of fill light from the front.  Otherwise, good portrait.', '2008-05-28 15:37:59.000000', NULL, 1),
(4730503, 681489, 73564, '<td valign="top">Wow!! This has to be a winner, looks like something I''d TRY to pull off. Nice butt.....</td>', 'Wow!! This has to be a winner, looks like something I''d TRY to pull off. Nice butt.....', '2008-05-28 15:38:39.000000', NULL, 1),
