(4731582, 681342, 43191, '<td valign="top">Nice colours and expresion on his face. The softness of the shot somehow detracts from the masculinity for me. I would like it a bit grittier to match the stubble on his face and the laugh lines round his eyes. 8</td>', 'Nice colours and expresion on his face. The softness of the shot somehow detracts from the masculinity for me. I would like it a bit grittier to match the stubble on his face and the laugh lines round his eyes. 8', '2008-05-28 23:53:00.000000', NULL, 1),
(4731587, 682483, 43191, '<td valign="top">Cute shot though I''m not keen on the chewed up food showing. The red and the blue enhance the youthfulness of this shot.8</td>', 'Cute shot though I''m not keen on the chewed up food showing. The red and the blue enhance the youthfulness of this shot.8', '2008-05-28 23:54:56.000000', NULL, 1),
