(4733663, 682386, 70265, '<td valign="top">very very nice. I love the addition of the hand on shoulder.</td>', 'very very nice. I love the addition of the hand on shoulder.', '2008-05-29 22:52:56.000000', NULL, 1),
(4733664, 682378, 70265, '<td valign="top">Great portrait of a young musician. Natural expression, good composition, and GREAT hair! Oh, and I love the black and white ....</td>', 'Great portrait of a young musician. Natural expression, good composition, and GREAT hair! Oh, and I love the black and white ....', '2008-05-29 22:53:01.000000', NULL, 1),
