(4733970, 680953, 33672, '<td valign="top">Great texture. Interesting eyes.</td>', 'Great texture. Interesting eyes.', '2008-05-30 01:28:44.000000', NULL, 1),
(4733972, 681701, 33672, '<td valign="top">There''s a thousand stories in those eyes. nice work</td>', 'There''s a thousand stories in those eyes. nice work', '2008-05-30 01:29:36.000000', NULL, 1),
